// ❌ N+1: 1 query for orders + 1 query PER order for its customer
var orders = await _db.Orders.Take(100).ToListAsync();
foreach (var o in orders)
{
    var name = o.Customer.Name;              // lazy load -> 100 extra round trips
    Console.WriteLine($"{o.Id} {name}");
}
// MiniProfiler shows: 101 commands, 480ms total, 100 of them at ~4ms

// ✅ Fix 1: projection in one query (usually the best answer)
var rows = await _db.Orders
    .Take(100)
    .Select(o => new { o.Id, CustomerName = o.Customer.Name })
    .ToListAsync();

// ✅ Fix 2: batch when the loop logic can't be one query
var orders = await _db.Orders.Take(100).ToListAsync();
var customerIds = orders.Select(o => o.CustomerId).Distinct().ToList();
var customers = await _db.Customers
    .Where(c => customerIds.Contains(c.Id))
    .ToDictionaryAsync(c => c.Id);           // 2 queries total regardless of N

